// Physical containers persist independently of their contents and filling history.
let mediumAssets=[...boxes.filter(b=>!b.analysis&&!b.blocked).map(b=>({id:b.id,name:'Caixa média '+b.id,type:'Caixa média'})),...Array.from({length:10},(_,i)=>({id:'MEDIA-'+String(i+1).padStart(3,'0'),name:'Caixa média '+(i+1),type:'Caixa média'}))],fillHistory=[];
const assetRecordsBeforePacking=assetRecords,addAssetBeforePacking=addAssetRecord,inspectionBeforePacking=commitInspection,detailBeforePacking=detail,resultBeforePacking=inspectionResult,labelsBeforePacking=showLabels,renderBeforePacking=render;
assetRecords=function(){return [...assetRecordsBeforePacking(),...mediumAssets]};
addAssetRecord=function(d){if(d.type!=='Caixa média')return addAssetBeforePacking(d);const id=assetIdKey(d.id),name=d.name.trim();if(!name||!/^[A-Z0-9]+(?:-[A-Z0-9]+)*$/.test(id))throw Error('Informe nome e ID válido.');if(assetRecords().some(a=>assetIdKey(a.id)===id))throw Error('ID já utilizado: '+id);mediumAssets.push({id,name,type:'Caixa média'});log('Caixa média cadastrada: '+id);return id};
newAsset=function(){const types=['Caixa preta','Caixa média','Freezer','Carrinho de sorvete'];openForm('Cadastrar bem com ID único',input('id','ID permanente / código QR')+input('name','Nome')+select('type','Tipo',types,1),d=>addAssetRecord({...d,type:types[+d.type]}))};
function packedContents(id){return boxes.find(b=>b.id===id&&b.qty>0&&!b.awaitingPacking)}
commitInspection=function(id,kind,d){if(kind!=='pop')return inspectionBeforePacking(id,kind,d);const p=buildInspection(id,kind,d),src=p.src,n=inspections.length,at=new Date().toISOString(),r={sourceId:id,kind,name:src.flavor,unit:'un',receiptId:src.receiptId,expected:src.qty,actual:p.actual,rejected:p.rejected,reason:p.reason,lot:src.lot,fifo:p.fifo,counts:p.counts,generated:[],fills:[],at,emptyPackages:[],scanPacking:true};boxes=boxes.filter(b=>b.id!==id);['AAA','B','C'].forEach((grade,i)=>{if(p.counts[i])boxes.push({...src,id:uniqueStockId('PEND-'),qty:p.counts[i],grade,loc:1,state:'Líquido',analysis:false,active:false,awaitingPacking:true,inspectionIndex:n,date:p.fifo,receivedDate:src.date,suggestedDestination:p.dests[i]})});if(p.rejected)boxes.push({...src,id:uniqueStockId('BLQ-'),qty:p.rejected,analysis:false,blocked:true,grade:'Bloqueado',loc:0,active:false,inspectionIndex:n});inspections.push(r);log(`Conferência ${id}: ${p.actual} contados, ${p.rejected} bloqueados. Aguardando vínculo com caixas físicas. ${p.reason}`);return n};
function packingRemainder(n){return boxes.filter(b=>b.awaitingPacking&&b.inspectionIndex===n).reduce((s,b)=>s+b.qty,0)}
function commitPack(poolId,rawId,rawQty,dest){const pool=boxes.find(b=>b.id===poolId&&b.awaitingPacking),id=assetIdKey(rawId),qty=Number(rawQty),loc=Number(dest);if(!pool||pool.qty<=0)throw Error('Não há saldo para encaixotar nesta classificação.');if(!mediumAssets.some(a=>a.id===id))throw Error('Caixa média não cadastrada. Cadastre seu ID em Cadastros antes de usar.');if(packedContents(id))throw Error('Esta caixa ainda contém estoque. Use uma caixa vazia.');if(!Number.isInteger(qty)||qty<=0||qty>100||qty>pool.qty)throw Error('Informe de 1 a 100 pops, sem exceder o saldo a encaixotar.');if(!Number.isInteger(loc)||loc<0||loc>=locations.length)throw Error('Destino inválido.');const at=new Date().toISOString(),fill={fillId:'ENV-'+String(fillHistory.length+1).padStart(4,'0'),boxId:id,qty,flavor:pool.flavor,grade:pool.grade,lot:pool.lot,date:pool.date,at,inspectionIndex:pool.inspectionIndex,receiptId:pool.receiptId,loc,state:'Líquido'};pool.qty-=qty;boxes=boxes.filter(b=>b.id!==id);boxes.push({...pool,id,qty,loc,awaitingPacking:false,active:false,packedAt:at,fillId:fill.fillId});fillHistory.push({...fill});const r=inspections[pool.inspectionIndex];r.generated.push(id);r.fills.push({...fill});log(`${fill.fillId}: ${id} recebeu ${qty} ${pool.flavor} ${pool.grade}, lote ${pool.lot}. Restam ${pool.qty} desta classe.`);return fill}
function packingPage(n){const r=inspections[n],pools=boxes.filter(b=>b.awaitingPacking&&b.inspectionIndex===n&&b.qty>0);go('Encaixotamento');$('app').innerHTML=`<div class="heading"><div><h1>Vincular às caixas físicas</h1><p>${esc(r.name)} · Lote ${esc(r.lot)} · ${esc(r.receiptId||'Exemplo inicial')}</p></div><button onclick="go('Conferência')">Voltar</button></div><div class="stats"><div class="stat"><span>Classificados e aprovados</span><strong>${r.counts.reduce((s,v)=>s+v,0)}</strong></div><div class="stat"><span>Encaixotados</span><strong>${r.fills.reduce((s,f)=>s+f.qty,0)}</strong></div><div class="stat"><span>Faltam encaixotar</span><strong>${packingRemainder(n)}</strong></div></div><div class="notice">Use o QR permanente de uma caixa média vazia. Digite ou use leitor que preenche texto. Câmera do celular ainda não conectada.</div>${pools.map(p=>`<form class="panel receipt-form" onsubmit="submitPack(event,'${p.id}',${n})"><h2>${p.grade} · ${p.qty} pops aguardando caixa</h2><div class="receipt-grid"><label>ID da caixa média<input name="boxId" list="empty-medium" placeholder="MEDIA-001" required onkeydown="if(event.key==='Enter'){event.preventDefault();this.form.elements.qty.focus()}"></label><label>Quantidade nesta caixa<input name="qty" type="number" min="1" max="${Math.min(100,p.qty)}" step="1" value="${Math.min(100,p.qty)}" required></label>${select('loc','Destino após encaixotar',locations,p.suggestedDestination)}</div><div class="actions"><button class="primary" type="submit">Confirmar caixa e conteúdo</button></div></form>`).join('')||'<section class="panel"><h2>Tudo encaixotado</h2><p>Cada quantidade está vinculada a uma caixa física identificada.</p></section>'}<datalist id="empty-medium">${mediumAssets.filter(a=>!packedContents(a.id)).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</datalist><p id="packing-error" role="alert" class="receipt-error"></p><section class="panel"><h2>Caixas vinculadas</h2>${r.fills.map(f=>`<div class="row"><div><strong>${f.boxId} · ${f.qty} pops · ${f.grade}</strong><small>${esc(f.flavor)} · ${esc(f.lot)} · ${f.fillId}</small></div><button onclick="mediumHistory('${f.boxId}')">Histórico</button></div>`).join('')||'<p>Nenhuma caixa vinculada ainda.</p>'}<div class="actions">${r.fills.length?`<button onclick="showLabels(${n})">Etiquetas de conteúdo / imprimir</button>`:''}<button onclick="go('Cadastros')">Cadastrar outra caixa</button><button onclick="go('Inventário')">Inventário</button></div></section>`}
function submitPack(e,poolId,n){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{commitPack(poolId,d.boxId,d.qty,d.loc);packingPage(n);toast('Conteúdo vinculado à caixa')}catch(err){$('packing-error').textContent=err.message}}
inspectionResult=function(n){if(inspections[n].scanPacking)return packingPage(n);return resultBeforePacking(n)};
detail=function(id){const b=boxes.find(b=>b.id===id);if(b?.awaitingPacking){packingPage(b.inspectionIndex);return}detailBeforePacking(id)};
function mediumHistory(id){const records=fillHistory.filter(f=>f.boxId===id),b=packedContents(id);openForm('Caixa '+id,`<p>${b?`${b.qty} ${esc(b.flavor)} · ${b.grade} · ${esc(b.lot)}`:'Vazia · disponível para novo enchimento'}</p><h2>Enchimentos anteriores</h2>${records.map(f=>`<div class="row"><div><strong>${f.fillId} · ${f.qty} pops no enchimento</strong><small>${esc(f.flavor)} · ${f.grade} · ${esc(f.lot)} · ${f.at.slice(0,10)}</small></div></div>`).join('')||'<p>Sem enchimentos registrados nesta sessão.</p>'}`,()=>{});}
showLabels=function(n){const r=inspections[n];if(!r.scanPacking)return labelsBeforePacking(n);go('Etiquetas');$('app').innerHTML=`<div class="heading no-print"><div><h1>Etiquetas de conteúdo</h1><p>O QR permanente identifica a caixa. Cada etiqueta registra um enchimento, sem substituir o histórico.</p></div><div class="actions"><button onclick="packingPage(${n})">Voltar</button><button class="primary" onclick="window.print()">Imprimir</button></div></div><div class="label-grid">${r.fills.map(f=>{const qr=qrcode(0,'M');qr.addData(f.boxId);qr.make();return `<article class="print-label"><div><strong>YOLO · ${esc(f.flavor)}</strong><h2>${f.boxId}</h2><p>${f.grade} · ${f.qty} pops ao encher<br>Lote: ${esc(f.lot)}<br>FIFO: ${esc(f.date)}<br>${f.fillId} · ${f.at.slice(0,10)}</p><small>DEMONSTRAÇÃO · ENCHIMENTO</small></div>${qr.createSvgTag(3,12)}</article>`}).join('')}</div>`};
render=function(){renderBeforePacking();if(view==='Conferência'||view==='Inventário'){$('app').insertAdjacentHTML('beforeend','<section class="panel"><h2>Aguardando encaixotamento</h2>'+inspections.map((r,n)=>r.scanPacking&&packingRemainder(n)>0?`<div class="row"><div><strong>${esc(r.name)} · ${packingRemainder(n)} pops</strong><small>${esc(r.lot)} · não disponível para retirada</small></div><button onclick="packingPage(${n})">Escanear caixas</button></div>`:'').join('')+'</section>')}if(view==='Embalagens'||view==='Cadastros')$('app').insertAdjacentHTML('beforeend','<section class="panel"><div class="row"><h2>Caixas médias permanentes</h2><button onclick="newAsset()">＋ Cadastrar</button></div>'+mediumAssets.map(a=>{const b=packedContents(a.id);return `<div class="row"><div><strong>${a.id} · ${esc(a.name)}</strong><small>${b?`${b.qty} pops · ${esc(b.flavor)} · ${b.grade}`:'Vazia · disponível'}</small></div><button onclick="mediumHistory('${a.id}')">Histórico</button></div>`}).join('')+'</section>')};
render();
